-- Rename the Course classification label PROGRAM_SPECIFIC to PROFESSIONAL.
--
-- "Program-specific" named the wrong concept. The courses it described are the
-- Professional Courses of a program (BSIT IT101/IT201/IT102, BSBA
-- BASOC/ECON/FM200): owned by one Academic Program and mapped through that
-- program's own Program Outcomes. The user corrected the terminology, so the
-- database label follows it. `POClassification.PROFESSIONAL` is a separate
-- concept (a Program Outcome category from ADR 0040) and is not the reason for
-- this rename; that vocabulary is unchanged.
--
-- Generated by `pnpm supabase:migration:diff -- rename_course_scope_to_professional`
-- and then reduced. The generator emitted a full enum rebuild (CREATE TYPE
-- "CourseScope_new" ... ALTER COLUMN TYPE USING course_scope::text ...
-- DROP TYPE "CourseScope_old"). `ALTER TYPE ... RENAME VALUE` reaches the same
-- end state without recasting every row through text, so this migration uses it.
-- Postgres also rewrites the column default and any CHECK constraint naming the
-- label, because both store parsed enum OIDs rather than label text.
--
-- Two tables persist the classification as a JSON string instead of as the
-- enum: `course_bound_evaluations.course_info_snapshot -> 'courseScope'` and
-- `academic_period_readiness_snapshots.contexts[] -> 'courseScope'`. Those keys
-- carry the same classification identifier, so they are corrected here in the
-- same transaction rather than left to split the vocabulary across two
-- representations. Only that one key's value changes, on rows that still hold
-- the retired label. These snapshots stay immutable in substance: no evidence,
-- no count, no schema version, and no timestamp is touched, and the regression
-- suite proves the remainder of each document is byte-identical. Audit trails
-- (`outcome_changes`) and comment prose are left alone.
--
-- The two triggers that reject snapshot updates are disabled by name so this
-- migration can perform that correction, then re-enabled before the
-- transaction commits. An aborted migration rolls both back with it.

BEGIN;

SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE public.academic_period_readiness_snapshots
  DISABLE TRIGGER academic_period_readiness_snapshots_immutable;
ALTER TABLE public.course_bound_evaluations
  DISABLE TRIGGER published_course_evaluation_snapshot_lock;

ALTER TYPE "CourseScope" RENAME VALUE 'PROGRAM_SPECIFIC' TO 'PROFESSIONAL';

UPDATE public.academic_period_readiness_snapshots
SET contexts = (
  SELECT jsonb_agg(
    CASE
      WHEN element ? 'courseScope' AND element ->> 'courseScope' = 'PROGRAM_SPECIFIC'
      THEN jsonb_set(element, '{courseScope}', '"PROFESSIONAL"'::jsonb, true)
      ELSE element
    END
    ORDER BY ordinal
  )
  FROM jsonb_array_elements(contexts) WITH ORDINALITY AS t(element, ordinal)
)
WHERE EXISTS (
  SELECT 1
  FROM jsonb_array_elements(contexts) AS t(element)
  WHERE element ? 'courseScope' AND element ->> 'courseScope' = 'PROGRAM_SPECIFIC'
);

UPDATE public.course_bound_evaluations
SET course_info_snapshot = jsonb_set(course_info_snapshot, '{courseScope}', '"PROFESSIONAL"'::jsonb, true)
WHERE course_info_snapshot ? 'courseScope'
  AND course_info_snapshot ->> 'courseScope' = 'PROGRAM_SPECIFIC';

ALTER TABLE public.academic_period_readiness_snapshots
  ENABLE TRIGGER academic_period_readiness_snapshots_immutable;
ALTER TABLE public.course_bound_evaluations
  ENABLE TRIGGER published_course_evaluation_snapshot_lock;

COMMIT;
